package com.lexorion.payroll.config;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;@Configuration public class OpenApiConfig{@Bean OpenAPI payrollOpenApi(){return new OpenAPI().info(new Info().title("Lexorion Payroll API").version("10F").description("Payroll foundation covering salary-template compensation snapshots, calculation, Pay Runs, finalization, immutable ledger history, and finalized payslip views. ADMIN users administer workspace-scoped payroll data. Processing and finalization require payroll.processing and follow DRAFT to PROCESSING to CALCULATED to FINALIZED, with PROCESSING to FAILED on atomic calculation failure. Finalization and ledger creation share one transaction. Ledger earnings are positive, deductions are negative, and NET_PAY is a negative balancing entry. Payslips read finalized calculation snapshots and never recalculate history. Internal UUIDs are never public. No tax engine, payment execution, statutory filing, benefits, attendance, billing, or Finance behavior is implemented." )).components(new Components().addSecuritySchemes("bearer",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearer"));}}
